def img(k, eager=False, cls=""):
    load = 'fetchpriority="high"' if eager else 'loading="lazy" decoding="async"'
    return f'<img {cls} src="images/{k}-800.webp" srcset="images/{k}-800.webp 800w, images/{k}-1600.webp 1600w" sizes="(max-width:640px) 100vw, 50vw" alt="{ALT[k]}" {load}>'

def when(e):
    return f'{e["d"]}, {e["mon"]} {e["day"]}, 2026 · {e["time"]}' if e["d"] else "Next date announced by email"

def card(e, featured_tag=False):
    tag = f'<span class="tag">{e["cat"]}</span>' + ('<span class="tag feat">Featured</span>' if featured_tag else "")
    price = f'{e["price"]} · {e["dur"]}' if e["price"] else e["dur"]
    act = '<a class="btn" href="#x-popups">Register</a>' if e["d"] else '<a class="btn ghost" href="#p-contact-visit">Tell me when</a>'
    return f'''<article class="card"><div class="ph">{img(e["img"])}{tag}</div><div class="bd"><p class="date">{when(e)}</p><h3>{e["t"]}</h3><p>{e["desc"]}</p><p class="meta">{price} · With <span class="italic">{e["who"]}</span></p><div class="acts">{act}<a class="link" href="#t-event">View details</a></div></div></article>'''

def row(e, compact=False):
    if e["d"]:
        w = f'<div class="when">{e["d"]}<b>{e["mon"]} {e["day"]}</b>{e["time"]}</div>'
        side = f'<div class="side"><p class="price">{e["price"]}</p><a class="btn" href="#x-popups">Register</a></div>'
    else:
        w = '<div class="when">Next date<b>By email</b>Ask to hear first</div>'
        side = '<div class="side"><p class="price">&nbsp;</p><a class="btn ghost" href="#p-contact-visit">Tell me when</a></div>'
    again = "".join(f'<span class="chip">Also {a}</span>' for a in e.get("again", []))
    chips = f'<div class="chips"><span class="chip">{e["cat"]}</span>{again}</div>'
    desc = "" if compact else f'<p>{e["desc"]}</p>'
    if compact: chips = ""
    return f'<div class="li">{w}<div><h4>{e["t"]}</h4>{desc}<p class="note">{e["dur"]} · With <span class="italic">{e["who"]}</span></p>{chips}</div>{side}</div>'

def upcoming(mod, title="Coming up"):
    items = [e for e in EV if e["mod"] == mod]
    return f'<div class="rowhead"><div><p class="eyebrow">Classes &amp; events</p><h2>{title}</h2></div><a class="link" href="#p-classes-events">See all classes & events</a></div><div class="list">{"".join(row(e, True) for e in items)}</div><p class="note" style="margin-top:14px"><span class="sample">Sample content</span> Dates, prices and facilitator names are samples.</p>'

def strip(n, name, url, title, desc):
    return f'<div class="strip"><div class="wrap"><span class="num">Page {n} · {name}</span><span class="url">{("groundwellcenter.com"+url) if url.startswith("/") else url}</span><span class="ttl">Title: {title}</span></div></div>'

def doors():
    return '''<div class="doors"><div><p class="eyebrow">Come together</p><h3>Classes &amp; Events</h3><p>Sound baths, workshops and community gatherings.</p><a class="btn" href="#p-classes-events">Find your next experience</a></div><div><p class="eyebrow">Time for you</p><h3>Individual Sessions</h3><p>Explore sound, Reiki and tuning forks in an individual session.</p><a class="btn" href="#p-individual-sessions">Explore sessions</a></div><div><p class="eyebrow">Deepen your practice</p><h3>Certifications &amp; Training</h3><p>Hands-on education for personal practice and professional development.</p><a class="btn" href="#p-certifications-training">Explore training</a></div></div>'''

def session_card(cat, t, desc, people="Choose Avery, Morgan, Quinn or any available practitioner."):
    return f'<div class="box"><p class="eyebrow">{cat}</p><h3>{t}</h3><p>{desc}</p><div class="lengths"><span>60 minutes · $70</span><span>90 minutes · $90</span></div><p class="note">{people}</p><a class="btn" href="#b-booking">Book a session</a></div>'

def modality(n, pid, name, url, title, lede, pic, about, expect, mod, extra="", feeling="curious"):
    return f'''<section id="{pid}" class="page" data-feeling="{feeling}">{strip(n, name, url, title, "")}
<div class="pagehead"><div class="wrap split"><div><p class="eyebrow">Explore offerings</p><h1 style="font-size:clamp(52px,5.4vw,80px)">{name}</h1><p class="lede" style="margin-top:18px">{lede}</p><div style="display:flex;gap:18px;flex-wrap:wrap;margin-top:22px"><a class="btn" href="#p-classes-events">See upcoming dates</a><a class="btn ghost" href="#p-contact-visit">Questions before booking?</a></div></div><div class="pic">{img(pic)}</div></div></div>
<div class="band sage tight" data-feeling="cared"><div class="wrap twocol"><div><h3 style="margin-bottom:12px">About {name.lower() if name!='Reiki' else 'Reiki'}</h3><p>{about}</p></div><div><h3 style="margin-bottom:12px">What to expect</h3><p>{expect}</p><span class="sample">Sample content</span></div></div></div>
<div class="band"><div class="wrap">{upcoming(mod)}</div></div>{extra}</section>'''

